test("public schemaVersion 1 parser accepts artifact graph and rejects non-artifactGraph top-level shapes", () => {
	const parsed = parsePublicWorkflow(
		artifactGraphWorkflowSpec({
			name: "impact-artifact",
			artifactGraph: {
				stages: [
					{
						id: "risk",
						type: "single",
						prompt: "Assess risk.",
						output: {
							controlSchema: "./schemas/risk.schema.json",
							analysis: { required: true },
							refs: { required: true },
						},
					},
					{
						id: "final",
						type: "reduce",
						from: ["risk"],
						inputPolicy: {
							requiredReads: ["risk.analysis"],
							enforcement: "fail",
						},
						prompt: "Synthesize.",
					},
				],
			},
		}),
	);
	assert.equal(parsed.schemaVersion, 1);
	assert.equal(parsed.name, "impact-artifact");
	assert.equal(parsed.artifactGraph.stages[0].id, "risk");
	assert.equal(
		parsed.artifactGraph.stages[1].inputPolicy.requiredReads[0],
		"risk.analysis",
	);

	assert.doesNotThrow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "verify",
							type: "single",
							prompt: "Verify without artifact access.",
							inputPolicy: { artifactAccess: "none" },
						},
					],
				},
			}),
		),
	);
	const artifactAccessWithRead = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{ id: "risk", type: "single", prompt: "Assess risk." },
						{
							id: "verify",
							type: "reduce",
							from: ["risk"],
							prompt: "Verify without artifact access.",
							inputPolicy: {
								artifactAccess: "none",
								requiredReads: ["risk.control"],
							},
						},
					],
				},
			}),
		),
	);
	assertIssue(
		artifactAccessWithRead,
		"$.artifactGraph.stages[1].inputPolicy.requiredReads",
		"must be empty",
	);
	const artifactAccessWithProjection = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "verify",
							type: "single",
							prompt: "Verify without artifact access.",
							sourceProjection: {},
							inputPolicy: { artifactAccess: "none" },
						},
					],
				},
			}),
		),
	);
	assertIssue(
		artifactAccessWithProjection,
		"$.artifactGraph.stages[0].inputPolicy.artifactAccess",
		"sourceProjection",
	);

	const invalidTopLevel = assertThrowsFlow(() =>
		parsePublicWorkflow({
			schemaVersion: 1,
			artifactGraph: {
				stages: [{ id: "main", type: "single", prompt: "Do." }],
			},
			unsupported: true,
		}),
	);
	assertIssue(invalidTopLevel, "$.unsupported", "unknown field");

	const legacyTaskType = assertThrowsFlow(() =>
		parsePublicWorkflow({
			schemaVersion: 1,
			artifactGraph: {
				stages: [{ id: "main", type: "task", prompt: "Do." }],
			},
		}),
	);
	assertIssue(
		legacyTaskType,
		"$.artifactGraph.stages[0].type",
		"must be one of: single, reduce, foreach, loop, dag, dynamic",
	);
});

test("artifact graph schema validates structured requiredReadPolicy path contracts", () => {
	const cappedWithoutPath = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{ id: "risk", type: "single", prompt: "Assess risk." },
						{
							id: "final",
							type: "reduce",
							from: ["risk"],
							prompt: "Synthesize.",
							inputPolicy: {
								requiredReadPolicy: [
									{ source: "risk", artifact: "control", maxChars: 200 },
								],
							},
						},
					],
				},
			}),
		),
	);
	assertIssue(
		cappedWithoutPath,
		"$.artifactGraph.stages[1].inputPolicy.requiredReadPolicy[0].path",
		"required when maxItems or maxChars",
	);

	const invalidPath = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{ id: "risk", type: "single", prompt: "Assess risk." },
						{
							id: "final",
							type: "reduce",
							from: ["risk"],
							prompt: "Synthesize.",
							inputPolicy: {
								requiredReadPolicy: [
									{
										source: "risk",
										artifact: "control",
										path: "$.claims[-1]",
										maxChars: 200,
									},
								],
							},
						},
					],
				},
			}),
		),
	);
	assertIssue(
		invalidPath,
		"$.artifactGraph.stages[1].inputPolicy.requiredReadPolicy[0].path",
		"optional array selectors/slices",
	);

	const parsed = parsePublicWorkflow(
		artifactGraphWorkflowSpec({
			artifactGraph: {
				stages: [
					{ id: "risk", type: "single", prompt: "Assess risk." },
					{
						id: "final",
						type: "reduce",
						from: ["risk"],
						prompt: "Synthesize.",
						inputPolicy: {
							requiredReadPolicy: [
								{
									source: "risk",
									artifact: "control",
									path: "$.claims[0:2]",
									maxItems: 2,
								},
							],
						},
					},
				],
			},
		}),
	);
	assert.equal(
		parsed.artifactGraph.stages[1].inputPolicy.requiredReadPolicy[0].path,
		"$.claims[0:2]",
	);
});

test("artifact graph schema validates sourcePolicy maxItems and schema refs", () => {
	const invalidPolicy = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "main",
							type: "single",
							prompt: "Do it.",
							sourcePolicy: "sometimes",
						},
					],
				},
			}),
		),
	);
	assertIssue(
		invalidPolicy,
		"$.artifactGraph.stages[0].sourcePolicy",
		"must be one of",
	);

	assert.doesNotThrow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "plan",
							type: "single",
							prompt: "Plan.",
						},
						{
							id: "items",
							type: "foreach",
							from: { source: "plan", path: "$.items" },
							maxItems: 5,
							each: { prompt: "Item ${item}" },
						},
					],
				},
			}),
		),
	);

	const badSchemaRef = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "main",
							type: "single",
							prompt: "Do it.",
							output: { controlSchema: "../schema.json" },
						},
					],
				},
			}),
		),
	);
	assertIssue(
		badSchemaRef,
		"$.artifactGraph.stages[0].output.controlSchema",
		"must stay inside the workflow bundle",
	);

	const badSchemaDoubleSlash = assertThrowsFlow(() =>
		parsePublicWorkflow(
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "main",
							type: "single",
							prompt: "Do it.",
							output: { controlSchema: ".//schemas/control.json" },
						},
					],
				},
			}),
		),
	);
	assertIssue(
		badSchemaDoubleSlash,
		"$.artifactGraph.stages[0].output.controlSchema",
		"must stay inside the workflow bundle",
	);
});

test("artifact graph schema accepts default-off fail-fast policy booleans", () => {
	const parsed = parsePublicWorkflow(
		workflowSpec("unit-scout", {
			artifactGraph: {
				failFast: true,
				cancelSiblingsOnFailure: true,
				cancelDescendantsOnParentFailure: true,
				stages: [{ id: "main", type: "single", prompt: "Do work." }],
			},
		}),
	);
	assert.equal(parsed.artifactGraph.failFast, true);
	assert.equal(parsed.artifactGraph.cancelSiblingsOnFailure, true);
	assert.equal(parsed.artifactGraph.cancelDescendantsOnParentFailure, true);

	const error = assertThrowsFlow(() =>
		parsePublicWorkflow(
			workflowSpec("unit-scout", {
				artifactGraph: {
					failFast: "yes",
					stages: [{ id: "main", type: "single", prompt: "Do work." }],
				},
			}),
		),
	);
	assertIssue(error, "$.artifactGraph.failFast", "must be a boolean");
});

test("artifact graph loader rejects unsupported controlSchema keywords", async () => {
	const cwd = makeProject();
	try {
		mkdirSync(join(cwd, "workflows", "schemas"), { recursive: true });
		writeFileSync(
			join(cwd, "workflows", "schemas", "bad.json"),
			JSON.stringify({
				type: "object",
				properties: { name: { type: "string", pattern: "^[a-z]+$" } },
			}),
		);
		writeFileSync(
			join(cwd, "workflows", "bad-schema.json"),
			JSON.stringify(
				artifactGraphWorkflowSpec({
					artifactGraph: {
						stages: [
							{
								id: "main",
								type: "single",
								prompt: "Do it.",
								output: { controlSchema: "./schemas/bad.json" },
							},
						],
					},
				}),
			),
		);
		await assert.rejects(
			() => loadWorkflow("bad-schema", cwd),
			(error) =>
				error instanceof WorkflowValidationError &&
				/pattern is not supported/.test(String(error)),
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

