test("compiler warns when sourceProjection paths match no source control schema", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "unit-scout", "read");
		mkdirSync(join(cwd, "schemas"), { recursive: true });
		writeFileSync(
			join(cwd, "schemas", "plan.schema.json"),
			JSON.stringify({
				type: "object",
				required: ["schema", "digest", "factSlots"],
				properties: {
					schema: { type: "string" },
					digest: { type: "string" },
					factSlots: {
						type: "array",
						items: {
							type: "object",
							properties: { id: { type: "string" } },
						},
					},
					sourcePolicy: {
						type: "object",
						properties: { mode: { type: "string" } },
					},
					extras: { type: "object", additionalProperties: true },
				},
			}),
		);
		const baseSpec = (include) =>
			artifactGraphWorkflowSpec({
				artifactGraph: {
					stages: [
						{
							id: "plan",
							type: "single",
							prompt: "Plan.",
							output: { controlSchema: "./schemas/plan.schema.json" },
						},
						{
							id: "research",
							type: "foreach",
							from: { source: "plan", path: "$.factSlots" },
							sourceProjection: { include },
							each: { prompt: "Research ${item}" },
						},
					],
				},
			});

		const good = await compileWorkflow(
			baseSpec([
				"$.factSlots",
				"$.sourcePolicy.mode",
				// resolves through array items
				"$.factSlots.id",
				// additionalProperties: true is skipped conservatively
				"$.extras.anythingGoes",
				// bracketed segments are skipped conservatively
				"$.factSlots[0].id",
			]),
			{ cwd, task: "Research" },
		);
		assert.equal(
			good.warnings.filter((w) => /sourceProjection/.test(w)).length,
			0,
			`unexpected sourceProjection warning: ${JSON.stringify(good.warnings)}`,
		);

		const bad = await compileWorkflow(
			baseSpec(["$.factSlots", "$.sourcePolicyTYPO.mode"]),
			{ cwd, task: "Research" },
		);
		const projectionWarnings = bad.warnings.filter((w) =>
			/sourceProjection/.test(w),
		);
		assert.equal(
			projectionWarnings.length,
			1,
			`expected exactly one sourceProjection warning: ${JSON.stringify(bad.warnings)}`,
		);
		assert.ok(
			/stage "research"/.test(projectionWarnings[0]) &&
				/\$\.sourcePolicyTYPO\.mode/.test(projectionWarnings[0]) &&
				/plan/.test(projectionWarnings[0]),
			`warning should name the stage, path, and source: ${projectionWarnings[0]}`,
		);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("experimental foreach cache-stable flag moves item payload after stable instructions", () => {
	const previous = process.env[EXPERIMENTAL_CACHE_STABLE_FOREACH_ENV];
	process.env[EXPERIMENTAL_CACHE_STABLE_FOREACH_ENV] = "1";
	try {
		const { tasks } = buildForeachGeneratedTasks(
			{
				stageId: "verify",
				foreach: {
					prompt: "Verify ${item} using the rubric.",
					injectRuntimeTask: false,
					roleText: "Use repository evidence.",
				},
			},
			undefined,
			["price is $1 and $& per unit"],
		);
		assert.equal(tasks.length, 1);
		assert.match(tasks[0].task, /workflow item payload below/);
		assert.doesNotMatch(tasks[0].task, /price is \$1 and \$& per unit/);
		const instructionsIndex = tasks[0].compiledPrompt.indexOf("# Instructions");
		const itemIndex = tasks[0].compiledPrompt.indexOf("# Workflow Item");
		const payloadIndex = tasks[0].compiledPrompt.indexOf(
			"# Workflow Item Payload",
		);
		assert.ok(instructionsIndex >= 0);
		assert.ok(itemIndex > instructionsIndex);
		assert.ok(payloadIndex > itemIndex);
		assert.match(tasks[0].compiledPrompt, /price is \$1 and \$& per unit/);
	} finally {
		if (previous === undefined)
			delete process.env[EXPERIMENTAL_CACHE_STABLE_FOREACH_ENV];
		else process.env[EXPERIMENTAL_CACHE_STABLE_FOREACH_ENV] = previous;
	}
});

test("simple JSON path reads own properties only and supports safe array selectors", () => {
	const inherited = { secret: "prototype-value" };
	const value = Object.create(inherited);
	value.safe = { answer: 42 };
	value.items = [
		{ id: "item-1", answer: 1 },
		{ id: "item-2", answer: 2 },
		{ id: "item-3", answer: 3 },
	];
	value.constructor = { answer: "blocked" };

	assert.equal(readSimpleJsonPath(value, "$.safe.answer"), 42);
	assert.equal(readSimpleJsonPath(value, "$.secret"), undefined);
	assert.equal(readSimpleJsonPath(value, "$.constructor.answer"), undefined);
	assert.equal(readSimpleJsonPath(value, "$.items[0].id"), "item-1");
	assert.deepEqual(readSimpleJsonPath(value, "$.items[1:3]"), [
		{ id: "item-2", answer: 2 },
		{ id: "item-3", answer: 3 },
	]);
	assert.deepEqual(readSimpleJsonPath(value, "$.items[*].answer"), [1, 2, 3]);
	assert.equal(readSimpleJsonPath(value.items, "$[1].id"), "item-2");
	assert.equal(readSimpleJsonPath(value, "$.items[-1]"), undefined);
});

