test("batched deep-review workflow preserves artifact denial on independent review stages", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "scout", "read, grep, find, ls");
		const specPath = join(
			process.cwd(),
			"workflows",
			"deep-review",
			"batched-devil-advocate.spec.json",
		);
		const spec = JSON.parse(readFileSync(specPath, "utf8"));
		for (const stageId of ["triage", "reviewers", "devil-advocate"]) {
			const stage = spec.artifactGraph.stages.find(
				(candidate) => candidate.id === stageId,
			);
			assert.equal(stage?.inputPolicy?.artifactAccess, "none");
		}
		const compiled = await compileWorkflow(spec, { cwd, specPath });
		const triage = compiled.tasks.find((task) => task.key === "triage.main");
		const reviewers = compiled.tasks.find(
			(task) => task.key === "reviewers.item",
		);
		const devilAdvocate = compiled.tasks.find(
			(task) => task.key === "devil-advocate.item",
		);
		for (const task of [triage, reviewers, devilAdvocate]) {
			assert.ok(task);
			assert.equal(task.artifactGraph.artifactAccess, "none");
			const prepared = await prepareDagTask(
				cwd,
				{
					runId: `batched_deep_review_${task.key}`,
					tasks: [
						{
							taskId: "task-1",
							specId: task.key,
							cwd,
							files: {
								result: `.pi/workflows/batched_deep_review_${task.key}/tasks/task-1/result.json`,
							},
						},
					],
				},
				{ tasks: [{ ...task, taskId: "task-1" }] },
				0,
			);
			assert.equal(
				prepared.runtime.toolProviders?.workflow_artifact,
				undefined,
			);
			assert.equal(prepared.runtime.tools.includes("workflow_artifact"), false);
			assert.doesNotMatch(prepared.compiledPrompt, /Workflow Artifact Inputs/);
		}
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow artifact telemetry summarizes stage status, retries, wall clock, and output bytes", () => {
	const run = {
		createdAt: "2026-06-08T00:00:00.000Z",
		updatedAt: "2026-06-08T00:02:00.000Z",
		tasks: [
			{
				stageId: "plan",
				status: "completed",
				startedAt: "2026-06-08T00:00:00.000Z",
				completedAt: "2026-06-08T00:00:10.000Z",
				files: { output: "a", stderr: "", result: "" },
			},
			{
				stageId: "verify",
				status: "completed",
				statusDetail: "context_or_request_too_large",
				lastMessage: "child Pi exceeded the model context window",
				startedAt: "2026-06-08T00:00:15.000Z",
				completedAt: "2026-06-08T00:00:45.000Z",
				outputRetry: {
					attempts: 1,
					reason: "workflow_output_invalid",
					repairMode: "new_session",
				},
				resumeEvents: [
					{
						at: "2026-06-08T00:00:50.000Z",
						fromStatus: "failed",
						fromStatusDetail: "workflow_output_invalid_exhausted",
						outputRetryAttempts: 2,
						outputRetryReason: "workflow_output_invalid_exhausted",
						outputRetryRepairMode: "same_session",
					},
				],
				files: { output: "b", stderr: "", result: "" },
			},
			{
				stageId: "verify",
				status: "interrupted",
				startedAt: "2026-06-08T00:00:20.000Z",
				completedAt: "2026-06-08T00:00:25.000Z",
				launchRetry: { attempts: 1 },
				files: { output: "c", stderr: "", result: "" },
			},
		],
	};
	const summary = summarizeWorkflowTelemetry(run, {
		outputBytesByTaskId: { a: 10, b: 20, c: 0 },
	});
	assert.equal(summary.wallClockMs, 120000);
	assert.equal(summary.taskCount, 3);
	assert.equal(summary.statusCounts.completed, 2);
	assert.equal(summary.statusCounts.interrupted, 1);
	assert.equal(summary.completion.health, "incomplete");
	assert.equal(summary.completion.clean, false);
	assert.equal(summary.completion.repaired, false);
	assert.equal(summary.completion.repairEvents, 5);
	assert.equal(summary.completion.contextLimitFailures, 1);
	assert.equal(summary.retryCounts.output, 3);
	assert.equal(summary.retryCounts.launch, 1);
	assert.equal(summary.retryReasons.output.workflow_output_invalid, 1);
	assert.equal(
		summary.retryReasons.output.workflow_output_invalid_exhausted,
		1,
	);
	assert.equal(summary.resumeCounts.events, 1);
	assert.equal(summary.resumeCounts.tasks, 1);
	assert.equal(summary.resumeStatusCounts.failed, 1);
	assert.equal(summary.outputRepairCounts.sameSession, 1);
	assert.equal(summary.outputRepairCounts.newSession, 1);
	assert.equal(summary.outputBytes, 30);
	assert.equal(summary.stages.verify.taskCount, 2);
	assert.equal(summary.stages.verify.durationMs, 35000);

	const clean = summarizeWorkflowTelemetry({
		createdAt: "2026-06-08T00:00:00.000Z",
		updatedAt: "2026-06-08T00:00:01.000Z",
		tasks: [{ status: "completed" }],
	});
	assert.equal(clean.completion.health, "clean");
	assert.equal(clean.completion.clean, true);

	const repaired = summarizeWorkflowTelemetry({
		createdAt: "2026-06-08T00:00:00.000Z",
		updatedAt: "2026-06-08T00:00:01.000Z",
		tasks: [{ status: "completed", outputRetry: { attempts: 1 } }],
	});
	assert.equal(repaired.completion.health, "repaired");
	assert.equal(repaired.completion.repaired, true);
});

