test("workflow web-source core redacts URLs and reads normalized snippets", async () => {
	const cwd = makeProject();
	try {
		const config = {
			runId: "workflow_unit",
			taskId: "task-1",
			cacheDir: join(
				cwd,
				".pi",
				"workflows",
				"workflow_unit",
				"web-source-cache",
			),
		};
		assert.equal(validateWorkflowWebUrl("file:///etc/passwd").ok, false);
		assert.equal(
			validateWorkflowWebUrl("http://169.254.169.254/latest/meta-data").ok,
			false,
		);
		assert.equal(validateWorkflowWebUrl("http://[::1]/").ok, false);
		assert.equal(validateWorkflowWebUrl("http://[::ffff:7f00:1]/").ok, false);
		assert.equal(validateWorkflowWebUrl("http://100.64.0.1/").ok, false);
		assert.equal(validateWorkflowWebUrl("http://198.18.0.1/").ok, false);
		assert.equal(
			sanitizeUrlForModel(
				"https://user:pass@example.test/path?token=secret&ok=1#access_token=secret",
			),
			"https://example.test/path?token=REDACTED&ok=1#access_token=REDACTED",
		);
		assert.equal(
			sanitizeUrlForModel(
				"https://example.test/path?jwt=abc&sid=def&sessionid=ghi&ok=1",
			),
			"https://example.test/path?jwt=REDACTED&sid=REDACTED&sessionid=REDACTED&ok=1",
		);
		const embeddedRedacted = sanitizeUrlForModel(
			"See https://user:pass@example.test/path?token=secret&ok=1 for details",
		);
		assert.doesNotMatch(embeddedRedacted, /user|pass|secret/);
		assert.match(
			embeddedRedacted,
			/https:\/\/example\.test\/path\?token=REDACTED&ok=1/,
		);
		const source = createWorkflowWebSource({
			config,
			url: "https://example.test/report?signature=secret#section",
			text: "The quoted value is “forty two” after whitespace.\nSecond line says GPU power is reported in milliwatts by the telemetry API.",
			title: "Example Report jwt=title-secret",
		});
		assert.equal(source.title, "Example Report jwt=REDACTED");
		const budget = createWorkflowWebVisibleBudget(180);
		const read = readWorkflowWebSourceSnippet({
			source,
			query: 'quoted value is "forty two"',
			maxChars: 60,
			budget,
		});
		assert.equal(read.status, "matched");
		assert.equal(read.matchType, "normalized");
		assert.match(read.quote, /forty two/);
		const termRead = readWorkflowWebSourceSnippet({
			source,
			claim: "Telemetry reports GPU power in milliwatts",
			terms: ["GPU power", "milliwatts", "telemetry API"],
			maxChars: 90,
			budget,
		});
		assert.equal(termRead.status, "matched");
		assert.equal(termRead.matchType, "terms");
		assert.match(termRead.quote, /milliwatts/);
		assert.deepEqual(termRead.matchedTerms, [
			"GPU power",
			"milliwatts",
			"telemetry API",
		]);
		assert.deepEqual(termRead.missingTerms, []);
		assert.equal(termRead.coverageRatio, 1);
		assert.equal(termRead.candidateOnly, true);
		const lateNeedle = "TARGET_MATCH_VALUE";
		const lateSource = createWorkflowWebSource({
			config,
			url: "https://example.test/late-match",
			text: `${"A".repeat(240)} ${lateNeedle} ${"B".repeat(240)}`,
		});
		const anchoredBudget = createWorkflowWebVisibleBudget(40);
		const anchoredRead = readWorkflowWebSourceSnippet({
			source: lateSource,
			query: lateNeedle,
			maxChars: 100,
			budget: anchoredBudget,
		});
		assert.equal(anchoredRead.status, "matched");
		assert.match(anchoredRead.quote, /TARGET_MATCH_VALUE/);
		assert.equal(anchoredBudget.used <= 40, true);
		const truncatedBudget = createWorkflowWebVisibleBudget(6);
		const truncatedRead = readWorkflowWebSourceSnippet({
			source: lateSource,
			query: lateNeedle,
			maxChars: 100,
			budget: truncatedBudget,
		});
		assert.equal(truncatedRead.status, "truncated");
		assert.match(truncatedRead.quote, /^TARGET/);
		assert.equal(source.redactedUrl.includes("secret"), false);
		assert.equal(await readWorkflowWebSource(config, "../escape"), undefined);
		await writeWorkflowWebSource(config, source);
		writeFileSync(
			join(config.cacheDir, "index.json"),
			JSON.stringify({
				schema: "workflow-web-source-index-v1",
				updatedAt: new Date().toISOString(),
				runId: config.runId,
				sources: [],
			}),
		);
		const rebuiltIndex = await readWorkflowWebSourceIndex(config);
		assert.ok(
			rebuiltIndex.sources.some(
				(entry) => entry.sourceRef === source.sourceRef,
			),
		);
		const foundByScan = await findWorkflowWebSourceByUrl(
			config,
			"https://example.test/report?signature=secret#section",
		);
		assert.equal(foundByScan.sourceRef, source.sourceRef);
		const differentSecret = await findWorkflowWebSourceByUrl(
			config,
			"https://example.test/report?signature=different#section",
		);
		assert.equal(differentSecret, undefined);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow web-source core anchors CJK normalized snippets and multi-match term windows", async () => {
	const cwd = makeProject();
	try {
		const config = {
			runId: "workflow_unit",
			taskId: "task-1",
			cacheDir: join(
				cwd,
				".pi",
				"workflows",
				"workflow_unit",
				"web-source-cache",
			),
		};
		const koreanText = `${"서론 ".repeat(18)}핵심 지표는 ＧＰＵ 전력 45㎿ 입니다. 결론은 같습니다. ${"부록 ".repeat(18)}`;
		const koreanSource = createWorkflowWebSource({
			config,
			url: "https://example.test/korean-report",
			text: koreanText,
		});

		const exactBudget = createWorkflowWebVisibleBudget(22);
		const exactRead = readWorkflowWebSourceSnippet({
			source: koreanSource,
			query: "GPU 전력",
			maxChars: 100,
			budget: exactBudget,
		});
		assert.equal(exactRead.status, "matched");
		assert.equal(exactRead.matchType, "normalized");
		assert.match(exactRead.quote, /ＧＰＵ 전력/);
		assert.equal(exactBudget.used, 22);

		const termBudget = createWorkflowWebVisibleBudget(28);
		const termRead = readWorkflowWebSourceSnippet({
			source: koreanSource,
			claim: "GPU 전력은 45MW로 기록됐다",
			terms: ["GPU 전력", "45MW"],
			maxChars: 100,
			budget: termBudget,
		});
		assert.equal(termRead.status, "matched");
		assert.equal(termRead.matchType, "terms");
		assert.match(termRead.quote, /ＧＰＵ 전력/);
		assert.match(termRead.quote, /45㎿/);
		assert.deepEqual(termRead.matchedTerms, ["GPU 전력", "45MW"]);
		assert.deepEqual(termRead.missingTerms, []);
		assert.equal(termBudget.used, 28);

		const multiText = `첫 anchor 조각은 혼자 있습니다. ${"중간 ".repeat(12)}두번째 anchor companion 조각은 더 완전합니다.`;
		const multiSource = createWorkflowWebSource({
			config,
			url: "https://example.test/multi-match",
			text: multiText,
		});
		const multiRead = readWorkflowWebSourceSnippet({
			source: multiSource,
			claim: "anchor companion",
			terms: ["anchor", "companion"],
			maxChars: 42,
			budget: createWorkflowWebVisibleBudget(42),
		});
		const firstAnchor = multiText.indexOf("anchor");
		const selectedAnchor = multiText.lastIndexOf("anchor");
		assert.equal(multiRead.status, "matched");
		assert.deepEqual(multiRead.matchedTerms, ["anchor", "companion"]);
		assert.match(multiRead.quote, /anchor companion/);
		assert.doesNotMatch(multiRead.quote, /첫 anchor/);
		assert.equal(multiRead.startOffset > firstAnchor, true);
		assert.equal(multiRead.startOffset <= selectedAnchor, true);
		assert.equal(
			multiRead.endOffset >= selectedAnchor + "anchor companion".length,
			true,
		);

		const secretSource = createWorkflowWebSource({
			config,
			url: "https://example.test/redaction-expansion",
			text: "token=x",
		});
		const secretRead = readWorkflowWebSourceSnippet({
			source: secretSource,
			query: "token=x",
			maxChars: "token=x".length,
			budget: createWorkflowWebVisibleBudget("token=x".length),
		});
		assert.equal(secretRead.status, "truncated");
		assert.equal(secretRead.truncated, true);
		assert.equal(secretRead.quote, "token=R");
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

