test("workflow_artifact can read deterministic JSON projections with caps", async () => {
	const cwd = makeProject();
	try {
		const runId = "workflow_unit";
		const runDir = join(cwd, ".pi", "workflows", runId);
		const producerDir = join(runDir, "tasks", "task-1");
		const consumerDir = join(runDir, "tasks", "task-2");
		mkdirSync(producerDir, { recursive: true });
		mkdirSync(consumerDir, { recursive: true });
		writeFileSync(
			join(producerDir, "control.json"),
			JSON.stringify(
				{
					claims: [
						{ id: "claim-1", text: "first" },
						{ id: "claim-2", text: "second" },
						{ id: "claim-3", text: "third" },
					],
					sourcePolicy: { preferred: ["primary"] },
				},
				null,
				2,
			),
		);
		writeFileSync(
			join(producerDir, "refs.json"),
			JSON.stringify([{ url: "https://example.test/ref" }], null, 2),
		);
		const manifestPath = join(consumerDir, "source-manifest.json");
		const ledgerPath = join(consumerDir, "read-ledger.jsonl");
		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "normalize",
						artifacts: {
							control: { path: join(producerDir, "control.json") },
							refs: { path: join(producerDir, "refs.json") },
						},
					},
				],
			}),
		);

		const result = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.claims",
				maxItems: 2,
				maxChars: 200,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);

		assert.match(
			result.content[0].text,
			/# workflow_artifact: normalize\.control path=\$\.claims/,
		);
		const { jsonText, payload } = workflowArtifactJsonPayload(result);
		assert.doesNotMatch(jsonText, /\n\s/);
		assert.deepEqual(
			payload.value.map((claim) => claim.id),
			["claim-1", "claim-2"],
		);
		assert.doesNotMatch(result.content[0].text, /claim-3/);
		assert.equal(result.details.projection.path, "$.claims");
		assert.equal(result.details.projection.totalItems, 3);
		assert.equal(result.details.projection.itemsReturned, 2);
		assert.equal(result.details.projection.itemsTruncated, true);
		assert.equal(result.details.truncated, true);
		assert.equal(
			result.details.projection.originalChars,
			JSON.stringify(payload.value).length,
		);
		assert.ok(
			result.details.projection.originalChars <
				JSON.stringify(payload.value, null, 2).length,
		);

		const compactClaims = JSON.stringify({ claims: payload.value });
		const prettyClaims = JSON.stringify({ claims: payload.value }, null, 2);
		assert.ok(compactClaims.length < prettyClaims.length);
		const compactBudget = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.claims",
				maxItems: 2,
				maxChars: JSON.stringify(payload.value).length,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.equal(compactBudget.details.projection.charsTruncated, false);
		assert.equal(
			workflowArtifactJsonPayload(compactBudget).payload.value[1].id,
			"claim-2",
		);

		const ledger = await readWorkflowArtifactReadLedger(ledgerPath);
		assert.equal(ledger.length, 2);
		assert.equal(ledger[0].source, "normalize");
		assert.equal(ledger[0].artifact, "control");
		assert.equal(ledger[0].path, "$.claims");
		assert.equal(ledger[0].maxItems, 2);
		assert.equal(ledger[0].maxChars, 200);

		const sourcePrefixed = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.normalize.claims",
				maxItems: 1,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.match(
			sourcePrefixed.content[0].text,
			/# workflow_artifact: normalize\.control path=\$\.claims/,
		);
		assert.equal(
			workflowArtifactJsonPayload(sourcePrefixed).payload.value[0].id,
			"claim-1",
		);

		const selectedClaim = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.normalize.claims[1]",
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.match(
			selectedClaim.content[0].text,
			/# workflow_artifact: normalize\.control path=\$\.claims\[1\]/,
		);
		assert.equal(
			workflowArtifactJsonPayload(selectedClaim).payload.value.id,
			"claim-2",
		);

		const slicedClaims = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.claims[1:3]",
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.deepEqual(
			workflowArtifactJsonPayload(slicedClaims).payload.value.map(
				(claim) => claim.id,
			),
			["claim-2", "claim-3"],
		);

		const artifactPrefixed = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.control.claims",
				maxItems: 1,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.match(
			artifactPrefixed.content[0].text,
			/# workflow_artifact: normalize\.control path=\$\.claims/,
		);

		const rootAlias = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "refs",
				path: "$.refs",
				maxChars: 200,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.match(
			rootAlias.content[0].text,
			/# workflow_artifact: normalize\.refs path=\$/,
		);

		const fieldAlias = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$.sourceRequirements",
				maxChars: 200,
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.match(
			fieldAlias.content[0].text,
			/# workflow_artifact: normalize\.control path=\$\.sourcePolicy/,
		);
		assert.deepEqual(workflowArtifactJsonPayload(fieldAlias).payload.value, {
			preferred: ["primary"],
		});

		writeFileSync(
			join(producerDir, "control.json"),
			JSON.stringify({ huge: "x".repeat(80_000) }, null, 2),
		);
		const cappedRoot = await handleWorkflowArtifactToolCall(
			{
				action: "read",
				source: "normalize",
				artifact: "control",
				path: "$",
			},
			{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
		);
		assert.equal(cappedRoot.details.truncated, true);
		assert.equal(cappedRoot.details.projection.maxChars, 50 * 1024);
		assert.ok(cappedRoot.details.returnedBytes < 60 * 1024);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow_artifact rejects path injection, unknown artifacts, and debug reads in workflow-task mode", async () => {
	const cwd = makeProject();
	try {
		const runId = "workflow_unit";
		const runDir = join(cwd, ".pi", "workflows", runId);
		const producerDir = join(runDir, "tasks", "task-1");
		const consumerDir = join(runDir, "tasks", "task-2");
		mkdirSync(producerDir, { recursive: true });
		mkdirSync(consumerDir, { recursive: true });
		writeFileSync(join(producerDir, "analysis.md"), "analysis\n");
		writeFileSync(join(producerDir, "prompt.md"), "prompt\n");
		const manifestPath = join(consumerDir, "source-manifest.json");
		const ledgerPath = join(consumerDir, "read-ledger.jsonl");
		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "plan",
						artifacts: {
							analysis: { path: join(producerDir, "analysis.md") },
							prompt: { path: join(producerDir, "prompt.md") },
						},
					},
				],
			}),
		);

		await assert.rejects(
			handleWorkflowArtifactToolCall(
				{ action: "read", source: "../plan", artifact: "analysis" },
				{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
			),
			/canonical workflow artifact source name/,
		);
		await assert.rejects(
			handleWorkflowArtifactToolCall(
				{ action: "read", source: "missing", artifact: "analysis" },
				{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
			),
			/unknown workflow artifact source/,
		);
		await assert.rejects(
			handleWorkflowArtifactToolCall(
				{ action: "read", source: "plan", artifact: "prompt" },
				{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
			),
			/not available in workflow-task access mode/,
		);
		await assert.rejects(
			handleWorkflowArtifactToolCall(
				{ action: "read", source: "plan", artifact: "bogus" },
				{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
			),
			/must be one of/,
		);

		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "evil",
						artifacts: { analysis: { path: join(cwd, "outside.md") } },
					},
				],
			}),
		);
		await assert.rejects(
			loadWorkflowSourceManifest(manifestPath, { runDir }),
			/inside the workflow run directory/,
		);

		writeFileSync(join(cwd, "outside-secret.md"), "secret\n");
		symlinkSync(join(cwd, "outside-secret.md"), join(producerDir, "link.md"));
		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "linked",
						artifacts: { analysis: { path: join(producerDir, "link.md") } },
					},
				],
			}),
		);
		await assert.rejects(
			handleWorkflowArtifactToolCall(
				{ action: "read", source: "linked", artifact: "analysis" },
				{ runId, taskId: "task-2", manifestPath, ledgerPath, runDir },
			),
			/must not be a symlink/,
		);

		const largePath = join(producerDir, "large.md");
		writeFileSync(largePath, "x".repeat(10_000));
		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "large",
						artifacts: { analysis: { path: largePath } },
					},
				],
			}),
		);
		const large = await handleWorkflowArtifactToolCall(
			{ action: "read", source: "large", artifact: "analysis" },
			{
				runId,
				taskId: "task-2",
				manifestPath,
				ledgerPath,
				runDir,
				maxBytes: 32,
			},
		);
		assert.equal(large.details.bytes, 10_000);
		assert.equal(large.details.returnedBytes, 32);
		assert.equal(large.details.truncated, true);
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("workflow_artifact extension registers and activates the tool", async () => {
	const cwd = makeProject();
	try {
		const runId = "workflow_unit";
		const runDir = join(cwd, ".pi", "workflows", runId);
		const producerDir = join(runDir, "tasks", "task-1");
		const consumerDir = join(runDir, "tasks", "task-2");
		mkdirSync(producerDir, { recursive: true });
		mkdirSync(consumerDir, { recursive: true });
		writeFileSync(
			join(producerDir, "analysis.md"),
			"extension-visible analysis\n",
		);
		const manifestPath = join(consumerDir, "source-manifest.json");
		const ledgerPath = join(consumerDir, "read-ledger.jsonl");
		writeFileSync(
			manifestPath,
			JSON.stringify({
				schema: "workflow-source-manifest-v1",
				runId,
				taskId: "task-2",
				sources: [
					{
						source: "plan",
						artifacts: {
							analysis: { path: join(producerDir, "analysis.md") },
						},
					},
				],
			}),
		);

		const registeredTools = [];
		const handlers = new Map();
		let activeTools = ["read"];
		const fakePi = {
			registerTool(tool) {
				registeredTools.push(tool);
			},
			on(event, handler) {
				handlers.set(event, handler);
			},
			getActiveTools() {
				return activeTools;
			},
			setActiveTools(tools) {
				activeTools = tools;
			},
		};

		registerWorkflowArtifactTool(fakePi, {
			runId,
			taskId: "task-2",
			manifestPath,
			ledgerPath,
			runDir,
		});
		assert.equal(registeredTools.length, 1);
		assert.equal(registeredTools[0].name, "workflow_artifact");
		handlers.get("session_start")?.({}, {});
		assert.deepEqual(
			new Set(activeTools),
			new Set(["read", "workflow_artifact"]),
		);

		const result = await registeredTools[0].execute("tool-call-1", {
			action: "read",
			source: "plan",
			artifact: "analysis",
		});
		assert.match(result.content[0].text, /extension-visible analysis/);
		const ledger = await readWorkflowArtifactReadLedger(ledgerPath);
		assert.equal(ledger.length, 1);
		assert.equal(ledger[0].source, "plan");
		assert.equal(ledger[0].artifact, "analysis");
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("structured required read policy enforces projection ledger rows separately from string reads", async () => {
	const cwd = makeProject();
	try {
		const taskDir = join(cwd, "task");
		mkdirSync(taskDir, { recursive: true });
		const ledgerPath = join(taskDir, "read-ledger.jsonl");
		const base = {
			schema: "workflow-artifact-read-v1",
			runId: "run",
			taskId: "task",
			source: "plan",
			artifact: "control",
			at: new Date().toISOString(),
			bytes: 1000,
		};
		writeFileSync(
			ledgerPath,
			[
				{
					...base,
					returnedBytes: 0,
					truncated: false,
					path: "$.items",
					maxChars: 0,
				},
				{
					...base,
					returnedBytes: 120,
					truncated: false,
					path: "$.wrong",
					maxChars: 200,
				},
				{
					...base,
					returnedBytes: 120,
					truncated: true,
					path: "$.items",
					maxChars: 200,
				},
			]
				.map((row) => JSON.stringify(row))
				.join("\n") + "\n",
		);

		const stringOnly = await checkRequiredArtifactReads(taskDir, [
			"plan.control",
		]);
		assert.deepEqual(stringOnly.missing, []);
		assert.deepEqual(stringOnly.projectionFailures, []);

		const maxCharsFailed = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.items",
					maxChars: 200,
					minReturnedBytes: 1,
				},
			],
		);
		assert.deepEqual(maxCharsFailed.missing, []);
		assert.match(maxCharsFailed.projectionFailures[0], /maxChars=200/);

		const cappedPolicyWithoutPathFailed = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					maxChars: 200,
				},
			],
		);
		assert.deepEqual(cappedPolicyWithoutPathFailed.missing, []);
		assert.match(
			cappedPolicyWithoutPathFailed.projectionFailures[0],
			/maxChars=200/,
		);

		const wrongPathFailed = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.missing",
					maxChars: 200,
				},
			],
		);
		assert.match(wrongPathFailed.projectionFailures[0], /path=\$\.missing/);

		const truncatedFailed = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.items",
					maxChars: 200,
					mustNotTruncate: true,
				},
			],
		);
		assert.match(truncatedFailed.projectionFailures[0], /mustNotTruncate=true/);

		// mustNotTruncate is always enforced: a truncated read fails the projection
		// even when the policy does NOT set mustNotTruncate. The only matching ledger
		// row for $.items at maxChars=200 is truncated, so the read must be rejected.
		const truncatedFailsWithoutFlag = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.items",
					maxChars: 200,
				},
			],
		);
		assert.deepEqual(truncatedFailsWithoutFlag.missing, []);
		assert.match(
			truncatedFailsWithoutFlag.projectionFailures[0],
			/path=\$\.items/,
		);

		const minReturnedBytesFailed = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.wrong",
					maxChars: 200,
					minReturnedBytes: 200,
				},
			],
		);
		assert.match(
			minReturnedBytesFailed.projectionFailures[0],
			/minReturnedBytes=200/,
		);

		const missing = await checkRequiredArtifactReads(
			taskDir,
			[],
			[{ source: "missing", artifact: "control", path: "$.items" }],
		);
		assert.deepEqual(missing.missing, ["missing.control"]);
		assert.deepEqual(missing.projectionFailures, []);

		writeFileSync(
			ledgerPath,
			[
				{
					...base,
					returnedBytes: 120,
					truncated: false,
					path: "$.wrong",
					maxChars: 200,
				},
				{
					...base,
					returnedBytes: 120,
					truncated: true,
					path: "$.items",
					maxChars: 200,
				},
				{
					...base,
					returnedBytes: 160,
					truncated: false,
					path: "$.items",
					maxChars: 200,
				},
			]
				.map((row) => JSON.stringify(row))
				.join("\n") + "\n",
		);
		const passes = await checkRequiredArtifactReads(
			taskDir,
			[],
			[
				{
					source: "plan",
					artifact: "control",
					path: "$.items",
					maxChars: 200,
					mustNotTruncate: true,
					minReturnedBytes: 120,
				},
			],
		);
		assert.deepEqual(passes, { missing: [], projectionFailures: [] });

		writeFileSync(
			ledgerPath,
			JSON.stringify({
				...base,
				returnedBytes: 160,
				truncated: false,
				path: "$.researchQuestions",
			}) + "\n",
		);
		const aliasPolicyPasses = await checkRequiredArtifactReads(
			taskDir,
			[],
			[{ source: "plan", artifact: "control", path: "$.questions" }],
		);
		assert.deepEqual(aliasPolicyPasses, {
			missing: [],
			projectionFailures: [],
		});
	} finally {
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("artifact graph workflow runs workflow artifacts and enforces required reads", async () => {
	const cwd = makeProject();
	try {
		writeAgent(cwd, "unit-scout", "read");
		mkdirSync(join(cwd, "workflows"), { recursive: true });
		writeFileSync(
			join(cwd, "workflows", "artifact.json"),
			JSON.stringify(
				artifactGraphWorkflowSpec({
					name: "artifact",
					artifactGraph: {
						stages: [
							{
								id: "analyze",
								type: "single",
								prompt: "Analyze.",
								output: {
									analysis: { required: true },
									refs: { required: true },
								},
							},
							{
								id: "final",
								type: "reduce",
								from: ["analyze"],
								sourceProjection: {
									include: ["$.digest", "$.items"],
									maxChars: 200,
								},
								inputPolicy: {
									requiredReads: [
										{
											source: "analyze",
											artifact: "control",
											path: "$.control.items",
											maxChars: 200,
											count: 1,
										},
									],
									enforcement: "fail",
								},
								prompt: "Finalize.",
							},
						],
					},
				}),
			),
		);

		let launchCount = 0;
		const runs = new Map();
		setSubagentApiForTests({
			async runSubagent(options) {
				launchCount += 1;
				const runId = `run_artifact_${launchCount}`;
				const attemptId = `attempt_artifact_${launchCount}`;
				const artifactDir = join(
					cwd,
					String(options.runsDir),
					runId,
					"attempts",
					attemptId,
				);
				mkdirSync(artifactDir, { recursive: true });
				const isFinal = launchCount === 2;
				const attemptStartedAt = new Date(Date.now() - 1000).toISOString();
				if (isFinal) {
					const [workflowRunId, taskId] = String(options.correlationId).split(
						":",
					);
					const taskDir = join(
						cwd,
						".pi",
						"workflows",
						workflowRunId,
						"tasks",
						taskId,
					);
					const ledgerPath = join(taskDir, "read-ledger.jsonl");
					assert.match(
						String(options.task),
						/Required reads before final output/,
					);
					assert.match(
						String(options.task),
						/# Required Workflow Artifact Reads/,
					);
					assert.doesNotMatch(
						String(options.task),
						/# Required Workflow Artifact Read Contents/,
					);
					assert.doesNotMatch(String(options.task), /Detailed analysis\./);
					writeFileSync(
						ledgerPath,
						[
							{
								schema: "workflow-artifact-read-v1",
								runId: workflowRunId,
								taskId,
								source: "analyze",
								artifact: "control",
								at: "2000-01-01T00:00:00.000Z",
								bytes: 18,
								returnedBytes: 18,
								truncated: false,
								path: "$.items",
								maxChars: 200,
							},
							{
								schema: "workflow-artifact-read-v1",
								runId: workflowRunId,
								taskId,
								source: "analyze",
								artifact: "control",
								at: new Date().toISOString(),
								bytes: 18,
								returnedBytes: 18,
								truncated: false,
								path: "$.items",
								maxChars: 200,
							},
						]
							.map((record) => JSON.stringify(record))
							.join("\n") + "\n",
					);
				}
				const control = isFinal
					? { schema: "stage-control-v1", digest: "final done", verdict: "ok" }
					: {
							schema: "stage-control-v1",
							digest: "analysis done",
							items: [{ id: "a" }],
						};
				const output = [
					"<control>",
					JSON.stringify(control),
					"</control>",
					"<analysis>",
					isFinal
						? "Final analysis after required read."
						: "Detailed analysis.",
					"</analysis>",
					"<refs>",
					"[]",
					"</refs>",
				].join("\n");
				writeFileSync(join(artifactDir, "output.log"), output);
				writeFileSync(join(artifactDir, "stderr.log"), "");
				writeFileSync(
					join(artifactDir, "result.json"),
					JSON.stringify({
						status: "completed",
						completedAt: new Date().toISOString(),
						startedAt: attemptStartedAt,
						exitCode: 0,
					}),
				);
				runs.set(runId, { runId, attemptId, artifactDir });
				return { runId, attemptId, status: "running" };
			},
			async reconcileSubagentRun() {
				return {};
			},
			async getSubagentStatus({ runId }) {
				const run = runs.get(runId);
				return {
					runId,
					attemptId: run.attemptId,
					backend: "headless",
					status: "completed",
					failureKind: null,
					startedAt: new Date().toISOString(),
					completedAt: new Date().toISOString(),
					logs: [
						{
							type: "output",
							path: "output.log",
							artifactCwd: run.artifactDir,
						},
						{
							type: "stderr",
							path: "stderr.log",
							artifactCwd: run.artifactDir,
						},
						{
							type: "result",
							path: "result.json",
							artifactCwd: run.artifactDir,
						},
					],
					metadata: { contextLengthExceeded: false },
					attempts: [
						{ attemptId: run.attemptId, status: "completed", pid: 12345 },
					],
				};
			},
			async interruptSubagent() {
				return {};
			},
		});

		const started = await runWorkflow("artifact", cwd, {
			task: "Run artifact graph",
		});
		const completed = await waitForRun(cwd, started.runId, 5_000);
		assert.equal(completed.status, "completed");
		assert.equal(launchCount, 2);
		const finalTask = taskBySpec(completed, "final.main");
		assert.equal(finalTask.status, "completed");
		const finalDir = dirname(join(cwd, finalTask.files.result));
		assert.equal(
			JSON.parse(readFileSync(join(finalDir, "control.json"), "utf8")).digest,
			"final done",
		);
		assert.match(
			readFileSync(join(finalDir, "analysis.md"), "utf8"),
			/Final analysis/,
		);
		const finalTaskPrompt = readFileSync(join(finalDir, "task.md"), "utf8");
		assert.ok(finalTaskPrompt.includes("Required reads before final output"));
		assert.ok(finalTaskPrompt.includes("# Required Workflow Artifact Reads"));
		assert.ok(finalTaskPrompt.includes("- analyze.control:"));
		assert.ok(finalTaskPrompt.includes("path=$.control.items"));
		assert.ok(finalTaskPrompt.includes("maxChars=200"));
		assert.ok(finalTaskPrompt.includes("count=1"));
		assert.doesNotMatch(finalTaskPrompt, /Detailed analysis\./);
		const finalManifest = JSON.parse(
			readFileSync(join(finalDir, "source-manifest.json"), "utf8"),
		);
		assert.deepEqual(finalManifest.sources[0].controlProjection, {
			digest: "analysis done",
			items: [{ id: "a" }],
		});
		assert.match(
			readFileSync(join(finalDir, "task.md"), "utf8"),
			/controlProjection/,
		);
	} finally {
		setSubagentApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

test("artifact graph output retry reuses confirmed subagent session", async () => {
	const cwd = makeProject();
	const previousSameSessionRepair =
		process.env[EXPERIMENTAL_SAME_SESSION_REPAIR_ENV];
	process.env[EXPERIMENTAL_SAME_SESSION_REPAIR_ENV] = "1";
	try {
		writeAgent(cwd, "unit-scout", "read");
		mkdirSync(join(cwd, "workflows"), { recursive: true });
		writeFileSync(
			join(cwd, "workflows", "session-retry.json"),
			JSON.stringify(
				workflowSpec("unit-scout", {
					artifactGraph: {
						stages: [{ id: "main", type: "single", prompt: "Analyze." }],
					},
				}),
			),
		);

		const launched = [];
		const runs = new Map();
		setSubagentApiForTests({
			async runSubagent(options) {
				launched.push(options);
				const runId = `run_session_${launched.length}`;
				const attemptId = `attempt_session_${launched.length}`;
				const artifactDir = join(
					cwd,
					String(options.runsDir),
					runId,
					"attempts",
					attemptId,
				);
				mkdirSync(artifactDir, { recursive: true });
				const output =
					launched.length === 1
						? "not workflow output"
						: [
								"<control>",
								JSON.stringify({ schema: "stage-control-v1", digest: "ok" }),
								"</control>",
								"<analysis>",
								"retry succeeded",
								"</analysis>",
								"<refs>",
								"[]",
								"</refs>",
							].join("\n");
				writeFileSync(join(artifactDir, "output.log"), output);
				writeFileSync(join(artifactDir, "stderr.log"), "");
				writeFileSync(
					join(artifactDir, "result.json"),
					JSON.stringify({
						status: "completed",
						completedAt: new Date().toISOString(),
						startedAt: new Date().toISOString(),
						exitCode: 0,
						metadata: {
							contextLengthExceeded: false,
							sessionId: options.sessionId,
							session: {
								id: options.sessionId,
								requested: true,
								disposition: launched.length === 1 ? "created" : "resumed",
							},
						},
					}),
				);
				runs.set(runId, { runId, attemptId, artifactDir });
				return { runId, attemptId, status: "running" };
			},
			async reconcileSubagentRun() {
				return {};
			},
			async getSubagentStatus({ runId }) {
				const run = runs.get(runId);
				return {
					runId,
					attemptId: run.attemptId,
					backend: "headless",
					status: "completed",
					failureKind: null,
					startedAt: new Date().toISOString(),
					completedAt: new Date().toISOString(),
					logs: [
						{
							type: "output",
							path: "output.log",
							artifactCwd: run.artifactDir,
						},
						{
							type: "stderr",
							path: "stderr.log",
							artifactCwd: run.artifactDir,
						},
						{
							type: "result",
							path: "result.json",
							artifactCwd: run.artifactDir,
						},
					],
					metadata: { contextLengthExceeded: false },
					attempts: [
						{ attemptId: run.attemptId, status: "completed", pid: 12345 },
					],
				};
			},
			async interruptSubagent() {
				return {};
			},
		});

		const started = await runWorkflow("session-retry", cwd, {
			task: "Run artifact graph",
		});
		const completed = await waitForRun(cwd, started.runId, 5_000);
		assert.equal(completed.status, "completed");
		assert.equal(launched.length, 2);
		const expectedSessionId = `pi-workflow.${started.runId}.task-1`;
		assert.equal(launched[0].sessionId, expectedSessionId);
		assert.equal(launched[1].sessionId, expectedSessionId);
		const task = taskBySpec(completed, "main.main");
		assert.equal(task.outputRetry.maxAttempts, 2);
		assert.equal(task.outputRetry.repairMode, "same_session");
		assert.equal(task.outputRetry.sessionId, expectedSessionId);
	} finally {
		if (previousSameSessionRepair === undefined)
			delete process.env[EXPERIMENTAL_SAME_SESSION_REPAIR_ENV];
		else
			process.env[EXPERIMENTAL_SAME_SESSION_REPAIR_ENV] =
				previousSameSessionRepair;
		setSubagentApiForTests(undefined);
		rmSync(cwd, {
			recursive: true,
			force: true,
			maxRetries: 5,
			retryDelay: 10,
		});
	}
});

